package main

import (
	"fmt"
	"strconv"
)

func main() {
	ages := []string{"21", "abc", "35", ""}
	count, sum := 0, 0
	for _, s := range ages {
		age, err := strconv.Atoi(s)
		if err != nil {
			fmt.Println("error:", err)
			continue
		}
		count++
		sum += age
	}
	fmt.Println(strconv.Itoa(count) + " valid ages")
	fmt.Printf("average: %.1f\n", float64(sum)/float64(count))
}

