package main

import (
	"fmt"
	"strconv"
)

func main() {
	prices := []string{"4.50", "12.25", "abc"}
	var total float64
	for _, s := range prices {
		p, err := strconv.ParseFloat(s, 64)
		if err != nil {
			fmt.Println("bad price:", strconv.Quote(s))
			continue
		}
		total += p
	}
	fmt.Println("total: " + strconv.FormatFloat(total, 'f', 2, 64))

	for _, s := range []string{"true", "yes"} {
		b, err := strconv.ParseBool(s)
		if err != nil {
			fmt.Println(err)
			continue
		}
		fmt.Println(s, "->", b)
	}
}

