package main

import (
	"fmt"
	"strconv"
)

func main() {
	readings := []string{"21.5", "-3.25", "n/a", "18"}
	flags := []string{"false", "1"}
	var total float64
	count := 0
	for _, s := range readings {
		r, err := strconv.ParseFloat(s, 64)
		if err != nil {
			fmt.Println("bad reading:", strconv.Quote(s))
			continue
		}
		total += r
		count++
	}
	avg := total / float64(count)
	fmt.Println("average: " + strconv.FormatFloat(avg, 'f', 1, 64))

	for _, s := range flags {
		b, err := strconv.ParseBool(s)
		if err != nil {
			fmt.Println(err)
			continue
		}
		fmt.Println(s, "->", b)
	}
}

