package main

import (
	"fmt"
	"strconv"
)

func main() {
	n := 255
	fmt.Println(strconv.FormatInt(int64(n), 2), strconv.FormatInt(int64(n), 16))
	fmt.Printf("%b %X\n", n, n)

	hex, err := strconv.ParseInt("ff", 16, 64)
	if err != nil {
		fmt.Println(err)
		return
	}
	oct, err := strconv.ParseInt("777", 8, 64)
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println(hex, oct)
	fmt.Println(0b11111111, 0o377, 0xFF)
}
